from cardio_1 import a, G
# E50 — Avitaminose A (E-06-Endocrinologie et métabolisme). Entrées conditionnelles : aucun terme existant dans G n’est écrasé.
def add(k, lit, full, d, ref=None):
    if k not in G:
        a(k, lit, full, d, ref)

add('RAE', [('R','Retinol'),('A','Activity'),('E','Equivalents')], 'Équivalents d’activité du rétinol', '<p>Unité qui exprime l’activité vitaminique A : 1 µg RAE équivaut à 1 µg de rétinol, 12 µg de β-carotène ou 24 µg d’autres caroténoïdes provitaminiques. Elle remplace l’ancien équivalent rétinol, qui comptait 6 µg de β-carotène.</p>', 'e50-rae')
add('RE', [('R','Retinol'),('E','Equivalents')], 'Équivalents rétinol', '<p>Ancienne unité d’activité de la vitamine A, qui comptait 6 µg de β-carotène pour 1 µg de rétinol. Les recommandations ESPEN de nutrition artificielle l’emploient encore pour les apports entéraux et parentéraux.</p>', 'e50-rae')
add('RBP', [('R','Retinol'),('B','Binding'),('P','Protein')], 'Protéine de liaison du rétinol', '<p>Protéine hépatique qui transporte le rétinol vers les tissus, liée à la transthyrétine. Protéine négative de la phase aiguë : l’inflammation la fait baisser.</p>', 'e50-rbp')
add('RBP4', [('R','Retinol'),('B','Binding'),('P','Protein'),('4','type 4')], 'Protéine de liaison du rétinol de type 4', '<p>Forme de la protéine de liaison du rétinol qui agit aussi comme adipokine, c’est-à-dire comme hormone du tissu adipeux. Elle modifie le rapport rétinol sur protéine de liaison chez la personne obèse.</p>', 'e50-rbp')
add('ESPEN', [('E','European'),('S','Society for'),('P','Parenteral and'),('E','Enteral'),('N','Nutrition')], 'Société européenne de nutrition clinique et de métabolisme', '<p>Société savante européenne qui publie les directives de nutrition clinique, dont celle de 2022 sur les micronutriments, rédigée sous la direction de Mette Berger (Lausanne).</p>', 'e50-sources-guides')
add('ECFS', [('E','European'),('C','Cystic'),('F','Fibrosis'),('S','Society')], 'Société européenne de mucoviscidose', '<p>Société qui publie avec l’ESPEN et l’ESPGHAN les directives de soins nutritionnels de la mucoviscidose.</p>', 'e50-mucoviscidose')
add('RYGB', [('R','Roux'),('Y','en Y'),('G','Gastric'),('B','Bypass')], 'Bypass gastrique Roux en Y', '<p>Opération qui relie une petite poche gastrique à une anse intestinale en Y. Elle expose à des carences en micronutriments, dont la vitamine A (18 % de carence biologique dans la méta-analyse 2026).</p>', 'e50-bariatrique')
add('BPD', [('B','Biliopancreatic'),('P','(biliopancréatique)'),('D','Diversion')], 'Dérivation biliopancréatique', '<p>Chirurgie bariatrique malabsorptive qui court-circuite une grande part de l’intestin grêle. La carence biologique en vitamine A atteint 59 % dans la méta-analyse 2026.</p>', 'e50-bariatrique')
add('BPD-DS', [('BPD','Biliopancreatic Diversion (dérivation biliopancréatique)'),('DS','Duodenal Switch (switch duodénal)')], 'Dérivation biliopancréatique avec switch duodénal', '<p>Variante de la dérivation biliopancréatique avec conservation du pylore. Carence biologique de 37,8 % ; délai oculaire médian de 14 à 27 ans.</p>', 'e50-bariatrique')
add('SMOB', [('S','Swiss'),('M','Morbid'),('O','Obesity'),('B','Bariatric (société suisse d’étude de l’obésité morbide et des maladies métaboliques)')], 'Société suisse pour l’étude de l’obésité morbide et des maladies métaboliques', '<p>Elle publie les directives suisses pour le traitement chirurgical de l’obésité (version du 1er juillet 2023), qui prévoient un suivi à vie.</p>', 'e50-bariatrique')
add('RAR', [('R','Retinoic'),('A','Acid'),('R','Receptor')], 'Récepteur de l’acide rétinoïque', '<p>Récepteur nucléaire activé par l’acide rétinoïque ; il règle l’expression de gènes de différenciation.</p>', 'e50-acide-retinoique')
add('RXR', [('R','Retinoid'),('X','X'),('R','Receptor')], 'Récepteur rétinoïde X', '<p>Récepteur nucléaire qui forme des hétérodimères avec RAR et avec le récepteur de la vitamine D.</p>', 'e50-acide-retinoique')
add('D-A-CH', [('D','Deutschland (Allemagne)'),('A','Austria (Autriche)'),('CH','Confoederatio Helvetica (Suisse)')], 'Valeurs de référence nutritionnelles de l’Allemagne, de l’Autriche et de la Suisse', '<p>Apports recommandés communs aux sociétés de nutrition de ces pays. La Suisse ne participe plus depuis 2022 ; la valeur de 2020 reste la dernière qui l’inclut.</p>', 'e50-apports')
add('AGP', [('A','Acid'),('G','Glyco'),('P','Protein')], 'Glycoprotéine acide', '<p>Protéine de l’inflammation (alpha-1-glycoprotéine acide). Son dosage, comme celui de la CRP, permet d’ajuster le rétinol sérique à l’inflammation.</p>', 'e50-inflammation')
add('XN', [('X','Xérophtalmie (stade de la classification de l’OMS)'),('N','Night blindness, cécité nocturne')], 'Stade XN, cécité nocturne', '<p>Premier stade de la classification OMS de la xérophtalmie ; correspond à E50.5.</p>', 'e50-xerophtalmie-oms')
add('X1A', [('X','Xérophtalmie'),('1','stade 1, conjonctive'),('A','sous-stade A, xérose conjonctivale')], 'Stade X1A, xérose conjonctivale', '<p>Conjonctive sèche et terne ; correspond à E50.0.</p>', 'e50-xerophtalmie-oms')
add('X1B', [('X','Xérophtalmie'),('1','stade 1, conjonctive'),('B','sous-stade B, taches de Bitot')], 'Stade X1B, taches de Bitot', '<p>Dépôts de cellules kératinisées de la conjonctive ; correspond à E50.1.</p>', 'e50-bitot')
add('X2', [('X','Xérophtalmie'),('2','stade 2, xérose cornéenne')], 'Stade X2, xérose cornéenne', '<p>Cornée terne ; urgence médicale ; correspond à E50.2. Dernier stade où la vision peut généralement être préservée complètement.</p>', 'e50-xerophtalmie-oms')
add('X3A', [('X','Xérophtalmie'),('3','stade 3, ulcération ou kératomalacie'),('A','moins d’un tiers de la cornée')], 'Stade X3A', '<p>Ulcération ou kératomalacie touchant moins d’un tiers de la cornée.</p>', 'e50-xerophtalmie-oms')
add('X3B', [('X','Xérophtalmie'),('3','stade 3, ulcération ou kératomalacie'),('B','un tiers ou plus de la cornée')], 'Stade X3B', '<p>Ulcération ou kératomalacie touchant un tiers ou plus de la cornée.</p>', 'e50-xerophtalmie-oms')
add('XS', [('X','Xérophtalmie'),('S','Scar, cicatrice cornéenne')], 'Stade XS, cicatrice cornéenne', '<p>Séquelle d’un épisode antérieur ; ne signe pas une carence active.</p>', 'e50-xerophtalmie-oms')
add('XF', [('X','Xérophtalmie'),('F','Fundus, fond d’œil')], 'Stade XF, fond d’œil xérophtalmique', '<p>Atteinte rétinienne visible au fond d’œil.</p>', 'e50-xerophtalmie-oms')
_E50 = {'0':'xérosis conjonctival','1':'taches de Bitot et xérosis conjonctival','2':'xérosis cornéen','3':'xérosis et ulcération de la cornée','4':'kératomalacie','5':'héméralopie','6':'cicatrices xérophtalmiques de la cornée','7':'autres manifestations oculaires','8':'autres manifestations de l’avitaminose A','9':'avitaminose A, sans précision'}
for _k, _v in _E50.items():
    add('E50.' + _k, [('E','chapitre des maladies endocriniennes, nutritionnelles et métaboliques'),('50','catégorie Avitaminose A'),('.' + _k, 'sous-catégorie : ' + _v)], 'Code CIM-10-GM 2024 E50.' + _k, '<p>Avitaminose A : ' + _v + '.</p>', 'e50-xerophtalmie-oms')

add('CIM', [('C','Classification'),('I','Internationale des'),('M','Maladies')], 'Classification internationale des maladies', '<p>Classification de l’Organisation mondiale de la santé utilisée pour coder les diagnostics ; ce cours emploie la version CIM-10-GM 2024.</p>', 'e50-xerophtalmie-oms')
add('DGE', [('D','Deutsche'),('G','Gesellschaft für'),('E','Ernährung')], 'Société allemande de nutrition', '<p>Société qui publie les valeurs de référence D-A-CH, avec les sociétés autrichienne et, jusqu’en 2022, suisse de nutrition.</p>', 'e50-apports')
add('X3', [('X','Xérophtalmie'),('3','stade 3, ulcération ou kératomalacie')], 'Stades X3A et X3B', '<p>Ensemble des stades d’ulcération ou de kératomalacie cornéenne, distingués selon qu’ils touchent moins d’un tiers ou un tiers et plus de la cornée.</p>', 'e50-xerophtalmie-oms')
add('Meyer-Heim', [('Meyer-Heim','nom d’auteur, non une abréviation')], 'Meyer-Heim, auteur du cas suisse de pseudotumeur cérébrale', '<p>Meyer-Heim, Landau et Boltshauser ont publié en 2002 un cas d’hypervitaminose A suisse.</p>', 'e50-suisse-serie')
